-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Fundamentos de UI / UX' and a.numero = 1
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 01 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 01', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 01 (20 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/FUNDAMENTOS-DE-UI-UX/ATIVIDADES/ATIVIDADE-PRATICA-AULA-01.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique a origem da palavra design e o que ela significa', 0.2, 'A palavra design vem de "desígnio", que significa propósito, plano ou intenção deliberada. Design, portanto, é planejar algo com finalidade, e não apenas embelezar.', 'Nota cheia: explica a origem ligada a desígnio (propósito, planejamento ou intenção) com as palavras do aluno. Metade: cita a ideia de propósito ou planejamento, mas sem a origem da palavra. Zero: em branco, errado ou só repete "design é bonito".'),
      (v_atividade, 1, 2, 'Diferencie design de decoração superficial, usando a ideia de propósito e planejamento', 0.4, 'Decoração trata apenas de aparência, enquanto design parte de um propósito e de um planejamento que resolvem uma necessidade. Por isso, a tela precisa cumprir uma tarefa, e não apenas agradar o olhar.', 'Nota cheia: diferencia decoração de design usando propósito e planejamento, com exemplo ou explicação própria. Metade: diferencia, mas sem usar propósito ou planejamento. Zero: em branco, errado ou não diferencia os dois conceitos.'),
      (v_atividade, 1, 3, 'Diga qual é o objetivo do design ao resolver uma necessidade humana concreta', 0.4, 'O objetivo do design é resolver uma necessidade humana concreta, equilibrando como o produto parece e como ele funciona. No caso da página de agendamento, o objetivo é a pessoa marcar a consulta sem erro.', 'Nota cheia: diz que o objetivo é resolver uma necessidade humana concreta e relaciona com forma e funcionamento ou com a tarefa do usuário. Metade: diz que o objetivo é resolver problemas, sem ligar à necessidade concreta da pessoa. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 2, 1, 'Defina forma e dê dois exemplos de elementos formais da tela citada', 0.2, 'Forma é o aspecto estético e visual do produto, como cores, tipografia, proporções e estilo gráfico. Dois exemplos na tela citada: as cores vibrantes e as animações exuberantes.', 'Nota cheia: define forma como aspecto visual/estético e cita dois elementos formais corretos da tela (cores, animações, tipografia, proporções etc.). Metade: define forma, mas cita apenas um exemplo ou exemplos imprecisos. Zero: em branco, errado ou confunde forma com função.'),
      (v_atividade, 2, 2, 'Defina função e explique por que a falha do botão de salvar compromete o produto', 0.4, 'Função é a utilidade prática, ou seja, o modo como o produto cumpre seu propósito de forma eficiente, segura e compreensível. Sem o botão de salvar, a pessoa não consegue concluir a tarefa principal, e o produto perde o valor.', 'Nota cheia: define função como utilidade prática e explica que a falha do botão impede a tarefa principal e compromete o produto. Metade: define função, mas a explicação do prejuízo é fraca ou ausente. Zero: em branco, errado ou confunde função com forma.'),
      (v_atividade, 2, 3, 'Explique a regra de ouro do design e diga como ela se aplica a esse aplicativo', 0.4, 'A regra de ouro diz que o design excelente surge quando forma e função cooperam sem disputar espaço. No aplicativo, os efeitos exuberantes disputam atenção com o botão de salvar, que precisa ser o elemento mais claro.', 'Nota cheia: enuncia a regra de ouro (forma e função cooperam sem disputar espaço) e aplica ao caso, dizendo que a forma atrapalha a função. Metade: enuncia a regra, mas a aplicação ao caso é superficial. Zero: em branco, errado ou não enuncia a regra.'),
      (v_atividade, 3, 1, 'Descreva o foco da estética pura e o que ela não precisa garantir', 0.2, 'A estética pura é a arte contemplativa, focada na autoexpressão do autor e na provocação de emoções subjetivas. Ela não precisa facilitar tarefas nem ser entendida da mesma forma por todos.', 'Nota cheia: descreve o foco (autoexpressão e emoção do autor) e diz que não precisa facilitar tarefas ou ser igualmente compreendida. Metade: descreve só o foco ou só o que não precisa garantir. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 3, 2, 'Descreva o foco do design funcional e como o seu sucesso é medido', 0.4, 'O design funcional é focado no usuário e no cumprimento de tarefas. O sucesso é medido pela clareza com que a pessoa realiza a tarefa sem cometer erros.', 'Nota cheia: descreve o foco no usuário e diz que o sucesso se mede pela clareza e pela ausência de erros na execução da tarefa. Metade: descreve o foco no usuário, mas não explica a medida de sucesso. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 3, 3, 'Explique por que a tela de transferência bancária deve ser avaliada pela clareza com que a pessoa conclui a tarefa', 0.4, 'A tela de transferência é um sistema funcional, e não uma obra de arte. Por isso, o que importa é a pessoa conseguir concluir a transferência de forma clara e sem erros.', 'Nota cheia: justifica a avaliação pela clareza da conclusão da tarefa, contrastando com a obra de arte. Metade: menciona a clareza ou a tarefa, sem a comparação. Zero: em branco, errado ou avalia pela beleza.'),
      (v_atividade, 4, 1, 'Diga em que século surgiu a prensa de tipos móveis e o que ela permitiu', 0.2, 'A prensa de tipos móveis de Gutenberg surgiu no século XV (por volta de 1450). Ela permitiu a replicação sistemática de textos e livros.', 'Nota cheia: cita o século XV (ou 1450) e diz que a prensa permitiu replicar textos e livros de forma sistemática. Metade: cita só o século ou só a replicação. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 4, 2, 'Explique por que os desenhistas passaram a padronizar fontes, margens e entrelinhas', 0.4, 'Com a replicação em série, desenhistas e impressores precisaram padronizar fontes, margens, entrelinhas e grades, para que a leitura fosse confortável e rápida.', 'Nota cheia: explica que a produção em série exigiu padronizar fontes, margens e entrelinhas/grades para a leitura confortável. Metade: cita a padronização, mas sem ligar à leitura ou à replicação. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 4, 3, 'Relacione esse marco com a necessidade de leitura confortável que existe até hoje em interfaces', 0.4, 'A preocupação com fontes legíveis, margens e entrelinhas continua nas interfaces de hoje, pois a pessoa precisa ler com conforto e rapidez em telas.', 'Nota cheia: relaciona o marco com a leitura confortável em interfaces atuais, com exemplo ou explicação própria. Metade: relaciona, mas de forma genérica. Zero: em branco, errado ou não relaciona com interfaces.'),
      (v_atividade, 5, 1, 'Descreva a mudança da manufatura artesanal para a produção seriada', 0.2, 'Na Revolução Industrial (séculos XVIII e XIX), as máquinas a vapor e as fábricas substituíram a manufatura artesanal, e os objetos passaram a ser fabricados aos milhares.', 'Nota cheia: descreve a passagem da produção artesanal para a produção em massa/seriada, com máquinas e fábricas. Metade: cita a fábrica ou a produção em série sem o contraste com o artesanato. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 5, 2, 'Explique por que surgiram identidades visuais padronizadas', 0.4, 'Como os objetos passaram a ser produzidos em série, surgiram identidades visuais padronizadas, para que cada marca fosse reconhecida em todos os produtos e cartazes.', 'Nota cheia: explica que a produção em massa exigiu identidades visuais padronizadas para reconhecimento das marcas. Metade: cita identidade visual, sem explicar o motivo da padronização. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 5, 3, 'Cite as informações que precisavam ser comunicadas com clareza a públicos diversos', 0.4, 'Precisavam ser comunicados com clareza preços, marcas, instruções de operação de equipamentos e regras de segurança, para públicos diversos.', 'Nota cheia: cita pelo menos duas informações (preços, marcas, instruções, segurança) e diz que o público era diverso. Metade: cita uma informação ou não menciona o público diverso. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 6, 1, 'Diga o que a Bauhaus uniu e em que ano foi fundada', 0.2, 'A Bauhaus uniu arte, artesanato e indústria e foi fundada em 1919, na Alemanha.', 'Nota cheia: diz que uniu arte, artesanato e indústria e cita 1919. Metade: cita apenas um dos dois elementos corretamente. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 6, 2, 'Explique a premissa de que a forma deve seguir a função', 0.4, 'A premissa de que a forma deve seguir a função significa que o aspecto visual de um objeto deve nascer da sua utilidade, e não de ornamentos que não ajudam o uso.', 'Nota cheia: explica a premissa com as palavras do aluno, ligando forma à utilidade e rejeitando ornamentos inúteis. Metade: repete a frase sem explicar o sentido. Zero: em branco, errado ou inverte a premissa.'),
      (v_atividade, 6, 3, 'Diga quais ornamentos você eliminaria na tela e por quê', 0.4, 'Eliminaria os ornamentos decorativos que não ajudam a concluir a ação principal, como sombras, gradientes e enfeites sem função, mantendo o destaque no botão da ação. A justificativa é que cada elemento deve ajudar a pessoa a concluir a tarefa.', 'Nota cheia: identifica ao menos um ornamento sem função, justifica pela ação principal e relaciona à premissa da Bauhaus. Metade: identifica ornamentos, mas sem a justificativa de função. Zero: em branco, errado ou propõe manter todos os ornamentos.'),
      (v_atividade, 7, 1, 'Descreva o que são grids modulares rígidos', 0.2, 'Grids modulares rígidos são estruturas de alinhamento matemático que dividem a página em colunas e módulos, organizando textos e imagens.', 'Nota cheia: descreve o grid como estrutura de alinhamento matemático/colunas e módulos. Metade: descreve de forma vaga (ex.: "linhas e colunas" sem o rigor). Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 7, 2, 'Explique o que é a tipografia sem serifa e cite um exemplo da época', 0.4, 'Tipografia sem serifa é a fonte sem os traços finais nas letras, mais limpa. Um exemplo da época é a Helvetica (criada em 1957).', 'Nota cheia: explica sem serifa (sem traços/ornamentos nas extremidades) e cita a Helvetica ou outra fonte sem serifa da época. Metade: explica o conceito, mas sem exemplo. Zero: em branco, errado ou confunde com serifa.'),
      (v_atividade, 7, 3, 'Explique por que essa estrutura é a base dos layouts de sites atuais', 0.4, 'A estrutura de grids e a tipografia limpa são a base direta dos layouts de sites atuais, pois organizam o conteúdo de forma previsível e legível em diferentes telas.', 'Nota cheia: explica que o estilo suíço é a base dos layouts atuais, com razão ligada à organização e à leitura. Metade: afirma a relação sem justificar. Zero: em branco, errado ou nega a relação.'),
      (v_atividade, 8, 1, 'Ordene os quatro marcos do mais antigo para o mais recente', 0.2, 'A ordem cronológica é: 1450 (Gutenberg), 1880 (cartazes litográficos), 1919 (Bauhaus) e 1957 (Helvetica e design suíço modular).', 'Nota cheia: ordena corretamente os quatro marcos, do mais antigo ao mais recente. Metade: acerta três dos quatro, ou inverte apenas um par. Zero: em branco, errado ou ordem invertida.'),
      (v_atividade, 8, 2, 'Descreva o que aconteceu em 1880 e em 1919', 0.4, 'Em 1880 surgiram os cartazes litográficos e a litografia colorida, que permitiram imprimir cartazes coloridos em grande escala. Em 1919, a Bauhaus uniu forma funcional e produção industrial.', 'Nota cheia: descreve corretamente os dois marcos (litografia colorida/cartazes em 1880; Bauhaus unindo forma funcional e produção industrial em 1919). Metade: descreve apenas um dos dois corretamente. Zero: em branco, errado ou troca os marcos.'),
      (v_atividade, 8, 3, 'Descreva o que a criação da Helvetica representou para o design modular em 1957', 0.4, 'Em 1957, a Helvetica e o design suíço modular criaram grids rígidos e tipografia sem serifa, que se tornaram a base dos layouts digitais.', 'Nota cheia: cita a Helvetica e o grid modular/tipografia sem serifa e relaciona ao design modular. Metade: cita apenas a Helvetica ou apenas o grid. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 9, 1, 'Descreva como era a interação nas interfaces de linha de comando', 0.2, 'Nas interfaces de linha de comando (CLI), a pessoa digitava comandos textuais complexos em telas monocromáticas escuras e apenas operadores treinados conseguiam usá-las.', 'Nota cheia: descreve a digitação de comandos textuais e a restrição a pessoas treinadas. Metade: descreve só a digitação de comandos. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 9, 2, 'Explique o que a GUI permitiu que as pessoas fizessem em vez de memorizar comandos', 0.4, 'A GUI permitiu que as pessoas apontassem e clicassem com o mouse em elementos familiares, como pastas, documentos, janelas e lixeiras, em vez de memorizar comandos.', 'Nota cheia: explica que a GUI troca comandos por apontar e clicar em elementos conhecidos (pastas, janelas, lixeira). Metade: cita apontar e clicar sem os elementos familiares. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 9, 3, 'Diga qual foi a contribuição do design para levar a tecnologia a pessoas sem treinamento técnico', 0.4, 'O design criou uma nova linguagem visual acessível, com ícones e metáforas do dia a dia, que permitiu usar a tecnologia sem treinamento técnico.', 'Nota cheia: diz que o design criou linguagem visual acessível (ícones, metáforas, janelas) para pessoas sem treinamento técnico. Metade: menciona acessibilidade do design sem ligar às metáforas ou ao público leigo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 10, 1, 'Descreva dois objetos do escritório físico usados como metáfora', 0.2, 'Dois objetos do escritório físico usados como metáfora são a pasta (ou arquivo) e a lixeira (ou a folha de papel). Também valem a mesa e a área de trabalho.', 'Nota cheia: cita dois objetos do escritório físico corretos (pasta, arquivo, folha, lixeira, mesa). Metade: cita um objeto correto. Zero: em branco, errado ou cita objeto digital.'),
      (v_atividade, 10, 2, 'Explique o que é uma metáfora visual deliberada de design', 0.4, 'A metáfora visual deliberada é a escolha intencional de representar um conceito digital por um objeto concreto conhecido, transportado para a tela.', 'Nota cheia: define metáfora visual deliberada como escolha intencional de um objeto conhecido para representar uma função digital. Metade: define como comparação, sem o caráter intencional. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 10, 3, 'Explique por que essa escolha reduz a necessidade de manuais técnicos', 0.4, 'Como a pessoa já conhece os objetos do escritório, ela aprende a usar o computador sem precisar ler manuais técnicos extensos, pois aproveita o conhecimento prévio.', 'Nota cheia: explica que o conhecimento prévio da pessoa torna o uso intuitivo e dispensa manuais técnicos. Metade: diz que reduz manuais, sem explicar o motivo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 11, 1, 'Descreva como eram as primeiras páginas da World Wide Web', 0.2, 'As primeiras páginas da World Wide Web eram documentos estáticos de texto azul sublinhado sobre fundo cinza, voltados a compartilhar artigos acadêmicos.', 'Nota cheia: descreve o caráter estático e textual das páginas (texto, poucos recursos, foco em artigos). Metade: descreve de forma genérica ("eram simples"). Zero: em branco, errado ou descreve a web atual.'),
      (v_atividade, 11, 2, 'Explique o papel das conexões discadas lentas e dos monitores de baixa resolução no design', 0.4, 'As conexões discadas lentas exigiam páginas leves, com pouco conteúdo pesado, e os monitores de baixa resolução limitavam o tamanho e a quantidade de elementos na tela.', 'Nota cheia: explica como as duas limitações (lentidão da conexão e baixa resolução) moldaram o design (páginas leves, layout limitado). Metade: cita as duas limitações sem relacionar ao design. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 11, 3, 'Diga por que o design gráfico precisou se adaptar quando empresas e pessoas comuns entraram na rede', 0.4, 'Quando empresas e pessoas comuns entraram na rede, o design precisou se adaptar às limitações técnicas e atender novos objetivos, como vender e conversar, com interfaces mais úteis e atraentes.', 'Nota cheia: explica a adaptação do design à entrada de novos públicos e objetivos, mantendo as limitações técnicas em mente. Metade: diz que o design mudou, sem explicar por quê. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 12, 1, 'Descreva o caráter fixo do meio impresso', 0.2, 'O meio impresso é fixo e imutável: as dimensões do papel (como A4 ou revista) não mudam, e a pessoa lê de forma passiva, virando páginas em sequência.', 'Nota cheia: descreve o caráter fixo (dimensões que não mudam) e a leitura passiva e sequencial. Metade: descreve só um dos dois aspectos. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 12, 2, 'Descreva o caráter dinâmico e responsivo da tela digital', 0.4, 'A tela digital é dinâmica e responsiva: o espaço muda conforme o aparelho e a tela reage a toques, cliques e rolagem.', 'Nota cheia: descreve a adaptação ao aparelho (responsividade) e a reação a toques, cliques ou rolagem. Metade: cita só a mudança de tamanho ou só a interação. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 12, 3, 'Explique por que a interação ativa exige um design diferente do design para papel', 0.4, 'Como a pessoa interage de forma ativa, o design precisa prever toques, cliques, rolagem e diferentes tamanhos de tela, e não apenas organizar um texto fixo como no papel.', 'Nota cheia: explica que a interação ativa exige prever gestos e respostas e adaptar a tela, diferente do papel. Metade: diz que é diferente, sem explicar o porquê. Zero: em branco, errado ou nega a diferença.'),
      (v_atividade, 13, 1, 'Nomeie a primeira etapa do ciclo e descreva-a', 0.2, 'A primeira etapa é a transposição direta, em que a nova mídia digital tenta copiar cegamente as regras do papel impresso antigo.', 'Nota cheia: nomeia a transposição direta e descreve a cópia das regras do papel. Metade: nomeia a etapa sem descrevê-la bem. Zero: em branco, errado ou nomeia outra etapa.'),
      (v_atividade, 13, 2, 'Justifique por que o site analisado está nessa etapa', 0.4, 'O site está na transposição direta, pois reproduz as margens e a diagramação do jornal impresso sem adaptar nada para o celular.', 'Nota cheia: justifica a etapa 1 pela cópia do jornal impresso sem adaptação ao celular. Metade: identifica a etapa, mas a justificativa é fraca. Zero: em branco, errado ou outra etapa sem justificativa.'),
      (v_atividade, 13, 3, 'Diga qual é a etapa seguinte desejada e como chegar a ela', 0.4, 'A etapa seguinte desejada é a maturidade funcional, com padrões e linguagem visual próprios da tecnologia digital, e o caminho inclui adaptar o layout ao celular e criar critérios de usabilidade. A etapa final é o foco humano, centrado na experiência do usuário.', 'Nota cheia: indica a maturidade funcional como próxima etapa e propõe ao menos uma ação concreta (adaptar ao celular, criar padrões próprios, usabilidade). Metade: indica a próxima etapa sem caminho concreto. Zero: em branco, errado ou sem próxima etapa.'),
      (v_atividade, 14, 1, 'Diga o que mudou na precisão da interação com o dedo em relação ao mouse', 0.2, 'Com o mouse, o ponteiro era preciso e minúsculo; com o dedo, a precisão é menor, o que aumenta o erro de toque.', 'Nota cheia: compara a precisão do ponteiro do mouse com a imprecisão do dedo. Metade: cita a imprecisão do dedo, sem a comparação. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 14, 2, 'Explique por que o tamanho mínimo dos botões deve ser de pelo menos 44×44 pixels', 0.4, 'Como a área de toque com o dedo é imprecisa, o tamanho mínimo recomendado é de pelo menos 44×44 pixels, para que a pessoa acerte o botão sem toques acidentais.', 'Nota cheia: indica 44×44 px (ou valor maior, como 48 px, citado no caso) e justifica pela imprecisão do dedo. Metade: indica o tamanho, sem justificar. Zero: em branco, errado ou valor diferente sem base.'),
      (v_atividade, 14, 3, 'Explique a função dos espaçamentos e dos gestos naturais nesse contexto', 0.4, 'Os espaçamentos evitam cliques acidentais entre botões próximos, e os gestos naturais, como pinça e deslizamento, tornam a interação mais intuitiva no toque.', 'Nota cheia: explica a função do espaçamento (evitar toques acidentais) e de ao menos um gesto natural (pinça ou deslizamento). Metade: cita só um dos dois elementos com explicação. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 15, 1, 'Descreva o esqueumorfismo e o objetivo de imitar texturas reais', 0.2, 'O esqueumorfismo (2007) imitava texturas reais, como couro, vidro e relevos 3D, para ensinar que os botões digitais podiam ser pressionados.', 'Nota cheia: descreve a imitação de materiais reais e o objetivo de mostrar que o botão pode ser pressionado. Metade: descreve só a imitação de texturas. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 15, 2, 'Descreva o Flat Design e o motivo de eliminar sombras e texturas', 0.4, 'O Flat Design (2012) eliminou sombras e texturas, com formas puras e cores sólidas, para dar clareza tipográfica e carregamento ultrarrápido.', 'Nota cheia: descreve a eliminação de sombras e texturas e o motivo (clareza e velocidade). Metade: descreve a eliminação, sem o motivo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 15, 3, 'Descreva o Material Design e como ele usa sombras para indicar camadas', 0.4, 'O Material Design (2014) trouxe de volta a noção de profundidade e camadas, usando sombras sutis para indicar o que está acima ou abaixo.', 'Nota cheia: descreve o uso de sombras sutis para indicar camadas (acima ou abaixo). Metade: cita sombras ou camadas, sem o sentido. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 16, 1, 'Descreva o foco do design inclusivo na acessibilidade digital', 0.2, 'O design inclusivo tem foco na acessibilidade digital, para que pessoas com diferentes capacidades visuais usem a interface com autonomia.', 'Nota cheia: descreve o foco em acessibilidade para diferentes capacidades visuais ou pessoas. Metade: cita acessibilidade sem o público. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 16, 2, 'Proponha uma ação ligada a alto contraste e explique o benefício', 0.4, 'Uma ação é aumentar o contraste entre o texto e o fundo dos campos e botões do portal, o que melhora a leitura para pessoas com baixa visão.', 'Nota cheia: propõe ação de alto contraste e explica o benefício para baixa visão. Metade: propõe contraste, sem o benefício. Zero: em branco, errado ou ação não relacionada.'),
      (v_atividade, 16, 3, 'Proponha uma ação ligada a leitores de tela ou personalização e explique o benefício', 0.4, 'Uma ação é garantir compatibilidade com leitores de tela (textos alternativos e rótulos nos campos) ou permitir personalização do tamanho da fonte, o que permite à pessoa usar o portal com autonomia.', 'Nota cheia: propõe ação de leitor de tela ou personalização e explica o benefício. Metade: propõe a ação sem o benefício. Zero: em branco, errado ou ação não relacionada.'),
      (v_atividade, 17, 1, 'Descreva a dificuldade de leitura que levou aos tamanhos de fonte dinâmicos', 0.2, 'A dificuldade de leitura de letras miúdas levou aos tamanhos de fonte dinâmicos, que permitem à pessoa ajustar o texto ao que consegue ler.', 'Nota cheia: liga a dificuldade de leitura de letras pequenas ao tamanho de fonte dinâmico. Metade: cita o tamanho de fonte sem a dificuldade de leitura. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 17, 2, 'Descreva o problema do cansaço visual que levou ao modo escuro', 0.4, 'O cansaço visual após horas em telas brilhantes levou ao modo escuro, que reduz o brilho e o desconforto da tela.', 'Nota cheia: liga o cansaço visual em telas brilhantes ao modo escuro e explica a redução do brilho. Metade: cita o modo escuro sem o cansaço. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 17, 3, 'Explique por que compreender a dor de quem usa é a base do design', 0.4, 'Compreender a dor de quem usa é a base do design, porque as soluções nascem das necessidades reais e dos problemas que as pessoas enfrentam.', 'Nota cheia: explica que o design parte das necessidades e dores reais de quem usa. Metade: afirma a frase sem explicar. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 18, 1, 'Defina a intenção estratégica do sistema na tela de agendamento', 0.2, 'A intenção estratégica da tela de agendamento é o objetivo do sistema: permitir que a pessoa marque uma consulta de forma rápida e sem erro (ou que a clínica organize seus horários).', 'Nota cheia: define a intenção como objetivo estratégico ligado ao agendamento da consulta. Metade: define de forma genérica ("facilitar o uso"). Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 18, 2, 'Descreva como formas, contrastes e hierarquia orientam a atenção da pessoa', 0.4, 'Formas, contrastes e hierarquia orientam a atenção: o botão de ação deve ser o elemento mais destacado, com cor forte e tamanho maior, guiando o olhar sem usar palavras.', 'Nota cheia: descreve como formas, contraste e hierarquia direcionam a atenção, com um exemplo na tela de agendamento. Metade: cita os três elementos sem explicar como orientam a atenção. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 18, 3, 'Diga como saber se o sucesso do usuário foi alcançado sem barreiras', 0.4, 'O sucesso é verificado quando a pessoa conclui o agendamento sem barreiras, o que pode ser medido com testes de tarefa ou taxa de conclusão.', 'Nota cheia: diz que o sucesso é a tarefa concluída sem barreiras e indica uma forma de conferir (teste, taxa de conclusão, observação). Metade: diz o critério, sem a forma de conferir. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 19, 1, 'Faça o diagnóstico visual do botão atual', 0.2, 'Visualmente, o botão atual é cinza claro sobre fundo branco, sem borda nem destaque, por isso passa despercebido e a pessoa não percebe onde confirmar.', 'Nota cheia: descreve a cor cinza claro sobre fundo branco, sem borda ou destaque, e a consequência de passar despercebido. Metade: descreve a cor, sem a consequência ou sem a falta de destaque. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 19, 2, 'Identifique a causa técnica do problema, ligada a contraste e hierarquia visual', 0.4, 'A causa técnica é a ausência de contraste e o desrespeito à hierarquia visual primária: a ação principal não se destaca dos demais elementos da tela.', 'Nota cheia: identifica falta de contraste e de hierarquia visual primária como causa técnica. Metade: cita só um dos dois conceitos. Zero: em branco, errado ou outra causa sem relação.'),
      (v_atividade, 19, 3, 'Proponha a solução de interface, com cor de destaque, posição e área de toque', 0.4, 'A solução é aplicar uma cor de destaque com alto contraste, posicionar o botão na base da tela e garantir área de toque mínima de 48 px (ou 44×44 px, no mínimo recomendado para o toque).', 'Nota cheia: propõe cor de destaque com alto contraste, posição (base da tela ou área de destaque) e área de toque adequada (44 ou 48 px). Metade: propõe a solução com dois dos três elementos. Zero: em branco, errado ou solução que não resolve a causa.'),
      (v_atividade, 20, 1, 'Descreva a etapa de diagnóstico visual', 0.2, 'No diagnóstico visual, o consultor identifica formas, contrastes e problemas de layout na tela existente, como o botão cinza claro sem destaque na página de agendamento.', 'Nota cheia: descreve o diagnóstico visual como identificação de formas, contrastes e problemas de layout em tela existente, aplicado ao caso. Metade: descreve a etapa, sem aplicar ao caso. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 20, 2, 'Descreva a etapa de pesquisa com usuário e diga que informações ela busca', 0.4, 'Na pesquisa com usuário, o consultor compreende objetivos, cenários reais de uso e queixas frequentes, por exemplo, por que as pessoas não encontram a confirmação do agendamento mobile.', 'Nota cheia: descreve a pesquisa como busca de objetivos, cenários reais e queixas, e diz que informações busca no caso. Metade: descreve a etapa sem ligar ao caso. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 20, 3, 'Descreva a etapa de prototipagem ágil e diga como ela ajuda a testar a sua proposta', 0.4, 'A prototipagem ágil esboça fluxos em storyboard, testa em papel e refina mock-ups digitais, o que permite validar a proposta antes de implementá-la.', 'Nota cheia: descreve storyboard, teste em papel ou mock-up e explica que a etapa permite testar a proposta antes da implementação. Metade: descreve a etapa, sem explicar como testa a proposta. Zero: em branco, errado ou fora do tema.');
end $$;
